/* Additional teaching selection and fresh checkpoints. Existing unit IDs stay unchanged. */
const COURSE_PLUS_LESSONS=[],COURSE_PLUS_QUESTIONS=[],COURSE_PLUS_GROUPS=[],COURSE_KANJI=[],COURSE_PLUS_READINGS=[];
function plusLesson(level,number,title,rule,pitfall,examples,qs){
 const id='plus-'+level.toLowerCase()+'-g'+String(number).padStart(2,'0'),group=level+'-'+Math.ceil(number/2);
 const questions=qs.map(([q,options,answer,why],i)=>({id:id+(i?'x':''),level,type:'grammar',title,q,options:options.split('|'),answer,why,lesson:id,group}));
 COURSE_PLUS_LESSONS.push({id,level,group,title,rule,pitfall,examples,questions});
}
function plusGroup(level,number,reading,listening){
 const key=level+'-'+number,make=([text,translation,qs],type)=>({text,translation,questions:qs.map(([q,options,answer,why],i)=>({id:'plus-'+key+'-'+type+i,level,type:type==='r'?'reading':'listening',title:level+' 第'+number+'阶段新题',text,translation,q,options:options.split('|'),answer,why,group:key}))});
 COURSE_PLUS_GROUPS.push({key,level,number,reading:make(reading,'r'),listening:make(listening,'l')});
}
plusLesson('N5',1,'は与が：话题和新信息','は提示接下来谈论的话题；回答“谁、什么”时，焦点常用が。并非每句都只能选其中一个，应结合问题和语境。','谁来？だれが来ますか → 田中さんが来ます。谈论田中则可说田中さんは学生です。',[
 ['だれが先生ですか。田中さんが先生です。','だれが せんせいですか。たなかさんが せんせいです。','谁是老师？田中是老师。'],['この店は、パンがおいしいです。','この みせは パンが おいしいです。','这家店的面包好吃。']],[
 ['回答“谁来了”：だれが来ましたか。——田中さん（　）来ました。','が|を|で|へ',0,'が标记回答“谁”的新信息。'],['谈论这座城，其中公园大：この町は、公園（　）大きいです。','が|を|で|へ',0,'町是话题，公園是“大”的主体。']]);
