// Register only additions; old IDs, option positions and completed-unit records remain intact.
const plusRotate=(q,n)=>{n%=q.options.length;q.options=[...q.options.slice(n),...q.options.slice(0,n)];q.answer=(q.answer-n+q.options.length)%q.options.length;};
for(const [i,l]of COURSE_PLUS_LESSONS.entries()){
 l.questions.forEach((q,j)=>{plusRotate(q,i+j);COURSE_PLUS_QUESTIONS.push(q);});
 grammar.push({...l.questions[0],id:l.id,level:l.level,title:l.title,topic:'专项辨析',rule:l.rule,tip:l.pitfall,desc:l.rule,examples:l.examples.map(([ja,kana,zh])=>[ja,kana+' / '+zh])});
}
for(const g of COURSE_PLUS_GROUPS){g.lessonIds=COURSE_PLUS_LESSONS.filter(l=>l.group===g.key).map(l=>l.id);g.ids=COURSE_PLUS_LESSONS.filter(l=>l.group===g.key).flatMap(l=>l.questions.map(q=>q.id));for(const [kind,arr,type]of [['reading',readings,'r'],['listening',listenings,'l']]){
 g[kind].questions.forEach((q,i)=>{plusRotate(q,g.number+i+2);COURSE_PLUS_QUESTIONS.push(q);arr.push({...q,type,unit:'plus-'+g.key});g.ids.push(q.id);});
}}
for(const [i,k]of COURSE_KANJI.entries())k.wordIds=k.examples.map(([word,reading,meaning,pos],j)=>{let w=words.find(w=>w.level===k.level&&w.word===word&&w.reading===reading);if(!w){w={id:'plus-'+k.level.toLowerCase()+'-k'+i+'w'+j,level:k.level,word,reading,meaning,pos};words.push(w);}return w.id;});
for(const [i,id]of [...new Set(COURSE_KANJI.flatMap(k=>k.wordIds))].entries()){
 const w=words.find(w=>w.id===id),pool=[...new Set(words.filter(x=>x.level===w.level&&x.reading!==w.reading).map(x=>x.reading))],start=i%(pool.length-3),q={id:'plus-read-'+id,word:id,level:w.level,type:'vocab',title:'汉字读音',q:`「${w.word}」の読み方はどれですか。`,options:[w.reading,...pool.slice(start,start+3)],answer:0,why:`${w.word}：${w.reading}。${w.meaning}。`};plusRotate(q,i);COURSE_PLUS_READINGS.push(q);
}
